name: aura-forms
description: >-
  Build Aura forms with useFormDynamic, Form error injection, and
  validateFormData (ajv JSON Schema) from @/utils/web-validation, submitted to
  a Next.js server action that re-validates with the same schema. Use when
  composing or fixing forms, server actions, or validation schemas.
---

# Aura forms

Guardrails live in `.agents/skills/aura/rules/forms.md`. This skill is the composition procedure.

Validate with ajv via `validateFormData` / JSON Schema; do not add zod, yup or valibot.

## Stack

* State: `useFormDynamic(initialValues, formRef?)` where values are `"text" | "textarea" | "select" | "checkbox"`.
* Fields: `formData.getFields()` or `formData.field(name)` → pass as `field` prop.
* Values: `formData.getValues()` for validate and submit.
* Errors: `validateFormData(schema, values)` from `@/utils/web-validation` → `errors` on `<Form>`. Form matches `error.instancePath.slice(1)` to `field.name`.
* Schema: one JSON Schema per form in a shared module such as `lib/validation/<name>.schema.ts`. The client and the server action import the same object.
* Submit: a Next.js server action. It checks auth and authorization, re-validates with the shared schema, and returns ajv `errors` that `<Form>` displays.
* Loading/error chrome: `formData.fetchStatus`, `formData.error`, `FormAlert`, `FormSubmit` with matching `form={id}`.

## Server actions

Treat every server action as a public endpoint. Inside the action, check the session and that the user may make this change, then validate the input again with `validateFormData`. Client validation is for feedback only. Take identity from the session, not from the submitted values.

## Example: schema, action, form

```ts
// lib/validation/profile.schema.ts
export const profileSchema = {
  type: "object",
  properties: {
    name: { type: "string", minLength: 1, maxLength: 100 },
    email: { type: "string", format: "email" },
  },
  required: ["name", "email"],
  additionalProperties: false,
  errorMessage: {
    properties: {
      name: "Enter your name (up to 100 characters).",
      email: "Enter a valid email address.",
    },
  },
};
```

```ts
// app/profile/actions.ts
"use server";

import type { ErrorObject } from "ajv";
import { verifySession } from "@/lib/auth";
import { db } from "@/lib/db";
import { profileSchema } from "@/lib/validation/profile.schema";
import { validateFormData } from "@/utils/web-validation";

export type ProfileActionResult =
  | { ok: true }
  | { ok: false; message: string; errors?: ErrorObject[] };

export async function updateProfile(
  values: Record<string, unknown>,
): Promise<ProfileActionResult> {
  const session = await verifySession();
  if (!session) return { ok: false, message: "Sign in to continue." };

  const { isValid, errors } = validateFormData(profileSchema, values);
  if (!isValid) {
    return { ok: false, message: "Please fix the errors below.", errors: errors ?? [] };
  }

  await db.user.update({
    where: { id: session.user.id },
    data: { name: String(values.name), email: String(values.email) },
  });
  return { ok: true };
}
```

```tsx
// app/profile/profile-form.tsx
"use client";

import { useRef, useState } from "react";
import type { ErrorObject } from "ajv";
import { Form, FormAlert, FormField, FormSubmit } from "@/components/ui/Form";
import { Input } from "@/components/ui/Input";
import { useFormDynamic } from "@/hooks/use-dynamic-form";
import { profileSchema } from "@/lib/validation/profile.schema";
import { validateFormData } from "@/utils/web-validation";
import { updateProfile } from "./actions";

export function ProfileForm() {
  const formRef = useRef<HTMLFormElement>(null);
  const formData = useFormDynamic({ name: "text", email: "text" }, formRef);
  const { name, email } = formData.getFields();
  const [serverErrors, setServerErrors] = useState<ErrorObject[]>();
  const { errors } = validateFormData(profileSchema, formData.getValues());

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    formData.touchForm();
    if (errors) {
      formData.setError("Please fix the errors below.");
      formData.setFetchStatus("error");
      return;
    }
    formData.setFetchStatus("loading");
    const result = await updateProfile(formData.getValues());
    if (!result.ok) {
      setServerErrors(result.errors);
      formData.setError(result.message);
      formData.setFetchStatus("error");
      return;
    }
    setServerErrors(undefined);
    formData.setFetchStatus("success");
  };

  return (
    <Form ref={formRef} onSubmit={handleSubmit} errors={errors ?? serverErrors} id="profile-form">
      <FormAlert formData={{ fetchStatus: formData.fetchStatus, error: formData.error }} />
      <FormField field={name} label="Name *"><Input type="text" /></FormField>
      <FormField field={email} label="Email *"><Input type="email" /></FormField>
      <FormSubmit fetchStatus={formData.fetchStatus} buttonProps={{ children: "Save" }} form="profile-form" />
    </Form>
  );
}
```

## Field wiring

* Native controls → `FormField` with `field.onChange`.
* Switch/checkbox → `FormSwitch` / `FormCheckbox` with `field.value` + `field.onCheckedChange`.
* Groups → `FormCheckboxGroup` / `FormRadioGroup` with `field.setValue`.
* Composed controls (Select, Combobox, Editor, …) → `field.setValue` in the change handler. Select stays uncontrolled + `onValueChange`.
* Show field errors only when `field.touch && errors?.length > 0` (Form field components do this via `serverInvalid`).

## After UI edits

Run skill `verify-aura-ui`. Keep editable controls ≥ 17px and do not override control padding at the call site.

#!/usr/bin/env node

import {
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { dirname, extname, isAbsolute, relative, resolve } from "node:path";

const MODEL = "gemini-2.5-flash-image";
const ALLOWED_ASPECTS = new Set([
  "1:1",
  "2:3",
  "3:2",
  "3:4",
  "4:3",
  "4:5",
  "5:4",
  "9:16",
  "16:9",
  "21:9",
]);

function usage(exitCode = 1) {
  console.error(`Usage:
  pnpm ai:image -- --manifest <plan.json> [--dry-run]
  pnpm ai:image -- --identity <note.md> --prompt "..." --output <path> [--aspect 16:9] [--dry-run]

The script reads GOOGLE_API_KEY or GEMINI_API_KEY from .env.`);
  process.exit(exitCode);
}

function parseArgs(argv) {
  const args = argv[0] === "--" ? argv.slice(1) : argv;
  const value = (flag) => {
    const index = args.indexOf(flag);
    return index >= 0 ? args[index + 1] : undefined;
  };

  if (args.includes("--help") || args.includes("-h")) usage(0);

  const manifest = value("--manifest");
  if (manifest) {
    return { manifest, dryRun: args.includes("--dry-run") };
  }

  const identity = value("--identity");
  const prompt = value("--prompt");
  const output = value("--output");
  if (!identity || !prompt || !output) usage();

  return {
    identity,
    images: [
      {
        prompt,
        output,
        aspectRatio: value("--aspect") ?? "16:9",
      },
    ],
    dryRun: args.includes("--dry-run"),
  };
}

function parseDotEnv(content) {
  const parsed = {};
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#")) continue;
    const match = line.match(/^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
    if (!match) continue;
    let value = match[2].trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    } else {
      value = value.replace(/\s+#.*$/, "");
    }
    parsed[match[1]] = value;
  }
  return parsed;
}

function loadProjectEnv(projectRoot) {
  const envPath = resolve(projectRoot, ".env");
  if (!existsSync(envPath)) return;
  const values = parseDotEnv(readFileSync(envPath, "utf8"));
  for (const [name, value] of Object.entries(values)) {
    if (process.env[name] === undefined) process.env[name] = value;
  }
}

function apiKey() {
  const key = process.env.GOOGLE_API_KEY || process.env.GEMINI_API_KEY;
  if (!key) {
    throw new Error(
      "MISSING_GEMINI_API_KEY: Add GOOGLE_API_KEY or GEMINI_API_KEY to .env, or ask the agent to use its native image-generation fallback.",
    );
  }
  return key;
}

function projectPath(projectRoot, input, label) {
  const absolute = resolve(projectRoot, input);
  const fromRoot = relative(projectRoot, absolute);
  if (
    isAbsolute(fromRoot) ||
    fromRoot === ".." ||
    fromRoot.startsWith(`..${process.platform === "win32" ? "\\" : "/"}`)
  ) {
    throw new Error(`${label} must stay inside the project: ${input}`);
  }
  return absolute;
}

function validateImage(image, index) {
  if (!image || typeof image !== "object") {
    throw new Error(`images[${index}] must be an object`);
  }
  if (typeof image.prompt !== "string" || !image.prompt.trim()) {
    throw new Error(`images[${index}].prompt is required`);
  }
  if (typeof image.output !== "string" || !image.output.trim()) {
    throw new Error(`images[${index}].output is required`);
  }
  const aspectRatio = image.aspectRatio ?? "16:9";
  if (!ALLOWED_ASPECTS.has(aspectRatio)) {
    throw new Error(
      `images[${index}].aspectRatio must be one of ${[...ALLOWED_ASPECTS].join(", ")}`,
    );
  }
  return { prompt: image.prompt.trim(), output: image.output, aspectRatio };
}

function readPlan(args, projectRoot) {
  if (!args.manifest) {
    return {
      identity: args.identity,
      images: args.images.map(validateImage),
      dryRun: args.dryRun,
    };
  }

  const manifestPath = projectPath(projectRoot, args.manifest, "Manifest path");
  const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
  if (typeof manifest.identity !== "string" || !manifest.identity.trim()) {
    throw new Error("Manifest identity must point to a blueprint identity note");
  }
  if (!Array.isArray(manifest.images) || manifest.images.length === 0) {
    throw new Error("Manifest images must contain at least one image");
  }
  return {
    identity: manifest.identity,
    images: manifest.images.map(validateImage),
    dryRun: args.dryRun,
  };
}

function readIdentity(projectRoot, identityInput) {
  const identityPath = projectPath(projectRoot, identityInput, "Identity path");
  if (!existsSync(identityPath)) {
    throw new Error(`Identity note not found: ${identityInput}`);
  }
  const identity = readFileSync(identityPath, "utf8").trim();
  if (!identity) throw new Error(`Identity note is empty: ${identityInput}`);
  if (/status:\s*needs-definition/i.test(identity)) {
    throw new Error(
      `IMAGE_IDENTITY_NOT_READY: Define ${identityInput} and set status: ready before generating.`,
    );
  }
  return identity.slice(0, 50_000);
}

function buildPrompt(identity, request) {
  return [
    "Create one polished production-ready image for a digital product.",
    "Follow this brand image identity as the source of truth:",
    "<image-identity>",
    identity,
    "</image-identity>",
    `Image request: ${request}`,
    "Render absolutely no text, lettering, logos, labels, captions, UI copy, or watermarks. Text and interface labels will be added in HTML.",
    "Keep the main subject crop-safe for responsive web use and avoid visual artifacts.",
  ].join("\n");
}

function extensionForMime(mimeType) {
  if (mimeType.includes("jpeg") || mimeType.includes("jpg")) return ".jpg";
  if (mimeType.includes("webp")) return ".webp";
  return ".png";
}

function outputForMime(projectRoot, output, mimeType) {
  const requested = projectPath(projectRoot, output, "Output path");
  const extension = extensionForMime(mimeType);
  const currentExtension = extname(requested);
  return currentExtension
    ? requested.slice(0, -currentExtension.length) + extension
    : requested + extension;
}

async function generate(key, prompt, aspectRatio) {
  const response = await fetch(
    `https://generativelanguage.googleapis.com/v1/models/${MODEL}:generateContent`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-goog-api-key": key,
      },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: {
          responseModalities: ["IMAGE"],
          responseFormat: {
            image: { aspectRatio },
          },
        },
      }),
    },
  );
  const payload = await response.json();
  if (!response.ok) {
    const message = payload?.error?.message ?? response.statusText;
    throw new Error(`Gemini API ${response.status}: ${message}`);
  }

  const parts = payload.candidates?.[0]?.content?.parts ?? [];
  for (const part of parts) {
    if (!part.inlineData?.data) continue;
    return {
      bytes: Buffer.from(part.inlineData.data, "base64"),
      mimeType: part.inlineData.mimeType || "image/png",
    };
  }

  const modelText = parts
    .map((part) => part.text)
    .filter(Boolean)
    .join("\n");
  throw new Error(
    modelText
      ? `No image returned. Model response: ${modelText}`
      : "No image returned by Gemini.",
  );
}

async function main() {
  const projectRoot = process.cwd();
  loadProjectEnv(projectRoot);
  const args = parseArgs(process.argv.slice(2));
  const plan = readPlan(args, projectRoot);
  const identity = readIdentity(projectRoot, plan.identity);
  const requests = plan.images.map((image) => ({
    ...image,
    resolvedPrompt: buildPrompt(identity, image.prompt),
  }));

  if (plan.dryRun) {
    for (const [index, image] of requests.entries()) {
      console.log(`--- image ${index + 1}: ${image.output} (${image.aspectRatio}) ---`);
      console.log(image.resolvedPrompt);
    }
    return;
  }

  const key = apiKey();
  console.log(`model=${MODEL} images=${requests.length}`);
  for (const image of requests) {
    const generated = await generate(
      key,
      image.resolvedPrompt,
      image.aspectRatio,
    );
    const outputPath = outputForMime(
      projectRoot,
      image.output,
      generated.mimeType,
    );
    mkdirSync(dirname(outputPath), { recursive: true });
    writeFileSync(outputPath, generated.bytes);
    console.log(`saved ${relative(projectRoot, outputPath)}`);
  }
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
});
